// #6a993d6ab2e4b167537ea9a3 — решение о найме и внутренние заметки: менеджер (business) и рекрутёр (user) по своему
// кандидату. Кейсы CAND-005, CAND-006, CAND-008.
// Решение/заметка ставятся ТОЛЬКО на кандидатах «QA-AUTO-HD…», созданных этим файлом (link_only — без писем/SMS).
// Звонков нет → у кандидата нет попытки, и панель решения в отчёте не показывается: решение и заметка идут тем же
// запросом, что и UI; результат проверяется в списке /candidates (UI) и в get_candidate_report.
// Кандидаты, решения и заметки не удаляются (в продукте удаления нет) — @data, не prod-safe.
import { test, expect } from '../../fixtures';
import { openWithApi, runStamp, Api } from '../support/api';
import { createCandidateLink, SIMULATION } from '../candidate-call/support';
import {
  HIRING, addNote, candidateId, createCandidateAssigned, decisionCellFor, getReport, isPerson, listCandidates, setDecision,
} from './hiring-support';

test.describe.configure({ mode: 'serial' });

let name = '';
let link = '';
let id = '';

test.describe('Кандидаты — решение о найме и внутренние заметки (#6a993d6ab2e4b167537ea9a3)', () => {
  test('business: три решения по своему кандидату — сразу в списке и фильтре, кто и когда; статус выполнения не меняется @desktop @data #6a993d6ab2e4b167537ea9a3', async ({ asUser }) => {
    test.setTimeout(180_000);
    const business = await asUser('business');
    name = `QA-AUTO-HD-${runStamp()}`;
    link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (решение + заметка), не удаляется` });
    const api = await openWithApi(business, '/candidates');
    const me = await api.userId();
    id = await candidateId(api, name);

    for (const status of Object.keys(HIRING) as (keyof typeof HIRING)[]) {
      const res = await setDecision(api, id, status);
      // UI считает успехом только непустой ответ (bundle: n?.length).
      expect(res.status(), `PATCH ${status}: ${await res.text()}`).toBe(200);
      expect(await res.json(), `PATCH ${status} не обновил строку`).toEqual([{ id }]);

      // Источник: AC2 «הסטטוס מתעדכן מיד ברשימה»; треб.6 — колонка и фильтр.
      const { row, cell } = await decisionCellFor(business, name);
      await expect(cell).toHaveText(HIRING[status]);
      // Источник: треб.4 — решение о найме отдельно от статуса выполнения.
      await expect(row).toContainText('קישור נוצר');
      await expect((await decisionCellFor(business, name, status)).cell).toHaveText(HIRING[status]);

      // Источник: треб.3 — «החלטה אנושית מזוהה»: кто и когда.
      const { hiring } = await getReport(api, id);
      expect(hiring?.status).toBe(status);
      expect(hiring?.changed_at, 'changed_at').toBeTruthy();
      expect(isPerson(hiring?.changed_by, me), `changed_by ${JSON.stringify(hiring?.changed_by)} ≠ ${me}`).toBe(true);
    }
  });

  test('business: внутренняя заметка видна команде с автором и временем; гость по ссылке её не получает @desktop @data #6a993d6ab2e4b167537ea9a3', async ({ asUser }) => {
    expect(id && link, 'нет кандидата из предыдущего теста').toBeTruthy();
    const business = await asUser('business');
    const api = await openWithApi(business, '/candidates');
    const me = await api.userId();
    const body = `QA-AUTO-NOTE-${runStamp()} הערה פנימית לבדיקה`;

    // p_report_id null — как шлёт UI для попытки без отчёта (reportId: e.report?.id ?? null).
    const res = await addNote(api, id, body, (await getReport(api, id)).report?.id ?? null);
    expect(res.status(), `add_internal_note: ${await res.text()}`).toBe(200);

    // Источник: AC3 / треб.2 — заметка команды с автором и временем.
    const note = ((await getReport(api, id)).notes ?? []).find((n) => n.body === body);
    expect(note, 'заметки нет в отчёте').toBeTruthy();
    expect(note!.created_at, 'created_at').toBeTruthy();
    expect(isPerson(note!.author, me, note!.created_by), `автор ${JSON.stringify(note!.author)} ≠ ${me}`).toBe(true);

    // Источник: AC3 — «גלוי רק לצוות»: у кандидата нет ни на экране, ни в ответах сети.
    const guest = await asUser('guest');
    const bodies: Promise<string>[] = [];
    guest.on('response', (r) => {
      if (r.request().resourceType() === 'fetch' || r.request().resourceType() === 'xhr') bodies.push(r.text().catch(() => ''));
    });
    const open = guest.waitForResponse((r) => r.url().includes('/rpc/candidate_open_link'));
    await guest.goto(link);
    expect((await open).status()).toBe(200);
    await expect(guest.locator('h1, h2').first()).toBeVisible();
    await expect(guest.locator('body')).not.toContainText(body);
    const leaked = (await Promise.all(bodies)).filter((t) => t.includes(body));
    expect(leaked, 'текст заметки в ответах сети у кандидата').toHaveLength(0);
  });

  test('рекрутёр по своему кандидату ставит решение и заметку — менеджер видит их с авторством рекрутёра @desktop @data #6a993d6ab2e4b167537ea9a3', async ({ asUser }) => {
    test.setTimeout(150_000);
    const recruiter = await asUser('user');
    const recApi: Api = await openWithApi(recruiter, '/candidates');
    const recruiterId = await recApi.userId();

    const business = await asUser('business');
    const own = `QA-AUTO-HDU-${runStamp()}`;
    await createCandidateAssigned(business, own, recruiterId, SIMULATION);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${own}» (назначен рекрутёру; решение + заметка), не удаляется` });

    // Рекрутёр видит своего кандидата.
    const mine = (await listCandidates(recApi)).filter((c) => c.full_name === own);
    expect(mine, 'рекрутёр не видит своего кандидата').toHaveLength(1);
    const ownId = mine[0].id;

    // Источник: треб.5 — «אפשרי רק למשתמש שהרשומה משויכת אליו או למנהל חשבון העסק».
    const dec = await setDecision(recApi, ownId, 'further_clarification_needed');
    expect(dec.status(), await dec.text()).toBe(200);
    expect(await dec.json()).toEqual([{ id: ownId }]);
    const body = `QA-AUTO-NOTE-U-${runStamp()} הערה של מגייס`;
    const note = await addNote(recApi, ownId, body, null);
    expect(note.status(), `add_internal_note: ${await note.text()}`).toBe(200);

    // Менеджер: в списке и в отчёте — решение и заметка рекрутёра.
    await expect((await decisionCellFor(business, own)).cell).toHaveText(HIRING.further_clarification_needed);
    const bizApi = await openWithApi(business, '/candidates');
    const report = await getReport(bizApi, ownId);
    expect(report.hiring?.status).toBe('further_clarification_needed');
    expect(isPerson(report.hiring?.changed_by, recruiterId), `changed_by ${JSON.stringify(report.hiring?.changed_by)} ≠ рекрутёр`).toBe(true);
    const n = (report.notes ?? []).find((x) => x.body === body);
    expect(n, 'менеджер не видит заметку рекрутёра').toBeTruthy();
    expect(isPerson(n!.author, recruiterId, n!.created_by), `автор заметки ${JSON.stringify(n!.author)} ≠ рекрутёр`).toBe(true);
  });
});
